INSERT INTO public.admins (role_level, id, email, hashed_password, full_name, is_active, created_at) VALUES (1, 1, 'admin@example.com', 'fbcb4a8160e2f43eda93a50cdf2dc681$a3fe489835d1aa2806cc0f44b834fc5e56223817e3144ff4655443b816a8d414', 'System Administrator', true, '2026-10-12 21:29:34.843567+07');
INSERT INTO public.categories (id, name, description, display_order, is_active, created_at) VALUES (1, 'Phở & Bún', 'Các món nước thanh ngọt, sợi bún phở mềm mịn, nước dùng hầm xương đậm đà chuẩn vị truyền thống.', 1, true, '2026-10-25 19:40:31.29821+07');
INSERT INTO public.categories (id, name, description, display_order, is_active, created_at) VALUES (2, 'Cơm & Xôi', 'Cơm niêu giòn đáy, cơm sườn nướng mật ong và xôi nếp dẻo thơm chắc dạ trọn vẹn từng bữa ăn.', 2, true, '2026-10-25 19:40:31.302717+07');
INSERT INTO public.categories (id, name, description, display_order, is_active, created_at) VALUES (3, 'Bánh mì', 'Bánh mì nướng giòn rụm, đầy đặn nhân pate thịt nguội, xúc xích và rau thơm tươi ngon.', 3, true, '2026-10-25 19:40:31.303783+07');
INSERT INTO public.categories (id, name, description, display_order, is_active, created_at) VALUES (4, 'Đồ ăn vặt', 'Nem chua rán giòn rụm, bánh tráng nướng, khoai tây lắc phô mai thơm ngon cho bữa xế vui vẻ.', 4, true, '2026-10-25 19:40:31.304922+07');
INSERT INTO public.categories (id, name, description, display_order, is_active, created_at) VALUES (5, 'Cà phê & Trà sữa', 'Cà phê đậm đà, trà hoa quả thanh mát giải nhiệt và trà sữa béo ngậy đầy topping.', 5, true, '2026-10-25 19:40:31.305925+07');
INSERT INTO public.categories (id, name, description, display_order, is_active, created_at) VALUES (6, 'Lẩu & Nướng', 'Nồi lẩu bốc khói nghi ngút và thịt nướng xèo xèo thơm phức lý tưởng cho những buổi hội ngộ sum vầy.', 6, true, '2026-10-25 19:40:31.305925+07');
